/* Inline SVG sticker plates for the A–Z picture pools (GAME-FLOW §15).
   All 390 pictures are drawn now — ui.js picturePlate() still falls through
   to the plate's own emoji whenever ART has no id, so a new picture never
   waits on art to be playable. Classroom-safe, no brands, no weapons.
   Adding a plate is: draw it here under its picture id, done. */

function svg(body) {
  return `<svg viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg" aria-hidden="true">${body}</svg>`;
}
const c = (cx, cy, r, f) => `<circle cx="${cx}" cy="${cy}" r="${r}" fill="${f}"/>`;
const e = (cx, cy, rx, ry, f, extra = '') => `<ellipse cx="${cx}" cy="${cy}" rx="${rx}" ry="${ry}" fill="${f}"${extra}/>`;
const r = (x, y, w, h, rx, f) => `<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${rx}" fill="${f}"/>`;
const p = (d, f, extra = '') => `<path d="${d}" fill="${f}"${extra}/>`;
const s = (d, stroke, w = 2) => `<path d="${d}" fill="none" stroke="${stroke}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;

